{"filePath":"c:\Users\kusha\Desktop\DailyDutyPanchavati-ui-rebuild (4)\src\app\main.tsx","content":"import { StrictMode, useEffect, useState } from "react";
import { createRoot } from "react-dom/client";
import "./styles.css";

type ChartRef = { date: string; lifecycle: string };

const mrWeekday: Record<string, string> = {
  Monday: "सोमवार", Tuesday: "मंगळवार", Wednesday: "बुधवार", Thursday: "गुरुवार",
  Friday: "शुक्रवार", Saturday: "शनिवार", Sunday: "रविवार",
};

function displayDate(date: string) {
  const [year, month, day] = date.split("-");
  return `${day}/${month}/${year}`;
}

function weekday(date: string) {
  const name = new Intl.DateTimeFormat("en-US", { weekday: "long", timeZone: "UTC" }).format(new Date(`${date}T00:00:00Z`));
  return mrWeekday[name] ?? "";
}

function App() {
  const current = location.pathname.match(/(\d{4}-\d{2}-\d{2})/)?.[1] ?? "2026-09-10";
  const [charts, setCharts] = useState<ChartRef[]>([]);
  const [date, setDate] = useState(current);
  const [language, setLanguage] = useState<"mr" | "en">("mr");
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    fetch("/api/charts").then((response) => response.json()).then(setCharts).catch(() => setCharts([]));
  }, []);

  const jump = (next: string) => {
    setDate(next);
    setMenuOpen(false);
    history.pushState({}, "", `/app/charts/${next}`);
  };

  return <div className="app-shell">
    <header className="app-nav">
      <div className="identity">
        <img src="/assets/police-logo.png" alt="महाराष्ट्र पोलीस" />
        <div><strong>पंचवटी पोलीस ठाणे</strong><span>नाशिक शहर | Panchavati Police Station</span></div>
      </div>
      <nav aria-label="मुख्य नेव्हिगेशन">
        <button className="nav-active">{language === "mr" ? "दैनिक कर्तव्य तक्ते" : "Daily Duty Charts"}</button>
        <button disabled title="Coming Soon">{language === "mr" ? "कार्यवाही" : "Operations"}</button>
        <button disabled title="Coming Soon">{language === "mr" ? "मास्टर डेटा" : "Master Data"}</button>
        <button disabled title="Coming Soon">{language === "mr" ? "ऐतिहासिक शोध" : "Historical Search"}</button>
      </nav>
      <div className="nav-actions">
        <button className="language" onClick={() => setLanguage(language === "mr" ? "en" : "mr")} aria-label="भाषा बदला">{language === "mr" ? "English" : "मराठी"}</button>
        <div className="date-control">
          <button onClick={() => setMenuOpen(!menuOpen)} aria-expanded={menuOpen}>{displayDate(date)} <span>{weekday(date)}</span>⌄</button>
          {menuOpen && <div className="date-menu" role="listbox">
            <strong>उपलब्ध तक्ते</strong>
            {charts.map((chart) => <button key={chart.date} onClick={() => jump(chart.date)} className={chart.date === date ? "selected" : ""}>
              <span>{displayDate(chart.date)} · {weekday(chart.date)}</span><small>{chart.lifecycle}</small>
            </button>)}
          </div>}
        </div>
        <span className="status">{charts.find((chart) => chart.date === date)?.lifecycle ?? "DRAFT"}</span>
        <a className="print-link" href={`/charts/${date}`} target="_blank" rel="noreferrer">प्रिंट</a>
      </div>
    </header>
    <main className="workspace">
      <div className="workspace-heading">
        <div><p className="eyebrow">पंचवटी तक्ता</p><h1>{language === "mr" ? "दैनिक कर्तव्य तक्ता" : "Daily Duty Chart"}</h1></div>
        <div className="heading-meta"><span>{displayDate(date)}</span><span>{weekday(date)}</span><a href={`/charts/${date}`} target="_blank" rel="noreferrer">प्रिंट आवृत्ती उघडा ↗</a></div>
      </div>
      <section className="document-frame" aria-label="दैनिक कर्तव्य तक्ता">
        <iframe title="दैनिक कर्तव्य तक्ता" src={`/charts/${date}`} />
      </section>
    </main>
  </div>;
}

createRoot(document.getElementById("root")!).render(<StrictMode><App /></StrictMode>);
"}

