+  const type = fileName.endsWith(".js") ? "text/javascript; charset=utf-8" : fileName.endsWith(".css") ? "text/css; charset=utf-8" : "text/html; charset=utf-8";
+  return reply.header("Content-Type", type).send(fs.readFileSync(abs));
