import { StrictMode, useEffect, useMemo, useState } from "react";
import { createRoot } from "react-dom/client";
import "./styles.css";

type Person = { staffId: number; nameMr: string; rankShortFormMr?: string | null; buckleNo?: string | null; rankCode?: string };
type Assignment = { assignmentId: number; shift: "DAY" | "NIGHT"; columnNo: number; sortOrder: number; dutyCode: string | null; dutyTitleMr: string | null; location: { nameMr: string; kind: string } | null; person: Person | null; allocationState: string; isBima: boolean; startTime: string | null; endTime: string | null; notesMr: string | null; roleMr?: string | null };
