const dayLabel = (date: string) => { const [year, month, day] = date.split("-"); return `${day}/${month}/${year}`; };
const personLabel = (person: Person | null) => person ? `${person.rankShortFormMr ?? person.rankCode ?? ""}${person.buckleNo ? ` ${person.buckleNo}` : ""} ${person.nameMr}`.trim() : "रिक्त";
const timeLabel = (a: Assignment) => a.startTime && a.endTime ? `${a.startTime.slice(0, 5)} ते ${a.endTime.slice(0, 5)}` : "";
const unique = <T,>(items: T[]) => [...new Set(items)];

function App() {
    const current = location.pathname.match(/(\d{4}-\d{2}-\d{2})/)?.[1] ?? "2026-09-10";
    const [date, setDate] = useState(current); const [charts, setCharts] = useState<ChartRef[]>([]); const [chart, setChart] = useState<Chart | null>(null);
    const [language, setLanguage] = useState<"mr" | "en">("mr"); const [menuOpen, setMenuOpen] = useState(false); const [editMode, setEditMode] = useState(false); const [selected, setSelected] = useState<Assignment | null>(null);
    const load = (next = date) => fetch(`/api/charts/${next}`).then((response) => response.json()).then(setChart);
    useEffect(() => { fetch("/api/charts").then((response) => response.json()).then(setCharts); load(); }, []);
    const jump = (next: string) => { setDate(next); setMenuOpen(false); history.pushState({}, "", `/app/charts/${next}`); load(next); window.scrollTo(0, 0); };
    return <div className="app-shell"><AppNav language={language} setLanguage={setLanguage} date={date} charts={charts} menuOpen={menuOpen} setMenuOpen={setMenuOpen} jump={jump} lifecycle={chart?.lifecycle ?? "DRAFT"} /><main className="workspace"><div className="chart-toolbar"><div><span className="eyebrow">पंचवटी तक्ता</span><h1>{language === "mr" ? "दैनिक कर्तव्य वाटप" : "Daily Duty Allocation"}</h1></div><div className="toolbar-actions"><span>{dayLabel(date)} · {chart?.weekdayMr ?? ""}</span>{chart?.lifecycle !== "FINALIZED" && <button onClick={() => setEditMode(!editMode)}>{editMode ? "पूर्वावलोकन" : "संपादन"}</button>}<a href={`/charts/${date}`} target="_blank" rel="noreferrer">प्रिंट</a></div></div>{chart ? <ChartView chart={chart} editMode={editMode} onSelect={setSelected} /> : <div className="loading">तक्ता लोड होत आहे…</div>}</main>{selected && <AssignmentEditor date={date} assignment={selected} onClose={() => setSelected(null)} onSaved={() => { setSelected(null); load(); }} />}</div>;
