+function SupportTable({ rows, onSelect, editMode }: { rows: Assignment[]; onSelect: (a: Assignment) => void; editMode: boolean }) { const titles = unique(rows.map((a) => a.dutyTitleMr ?? a.roleMr ?? "कर्तव्य")); return <div className="support-table">{titles.map((title) => <div className="support-column" key={title}><b>{title}</b>{rows.filter((a) => (a.dutyTitleMr ?? a.roleMr ?? "कर्तव्य") === title).map((a) => <Slot key={a.assignmentId} a={a} onSelect={onSelect} editMode={editMode} />)}</div>)}</div>; }
+function OfficerGrid({ chart }: { chart: Chart }) { return <div className="officer-grid">{chart.officerSummary.slice(0, 4).map((officer) => <div className="officer-block" key={officer.rowNo}><strong>{officer.officerText}</strong><span>{officer.dutyText}</span><div><span>रायटर <em>रिक्त</em></span><span>RTPC दिवस <em>रिक्त</em></span><span>RTPC रात्र <em>रिक्त</em></span></div></div>)}</div>; }
+function DutyLane({ title, rows, groups, onSelect, editMode }: { title: string; rows: Assignment[]; groups: (r: Assignment[]) => { title: string; rows: Assignment[] }[]; onSelect: (a: Assignment) => void; editMode: boolean }) { return <div className="duty-lane"><h2>{title}</h2>{groups(rows).slice(0, 14).map((group) => <div className="duty-group" key={group.title}><b>{group.title}</b>{group.rows.map((a) => <Slot key={a.assignmentId} a={a} onSelect={onSelect} editMode={editMode} />)}</div>)}</div>; }
+function DenseRegister({ title, groups, onSelect, editMode, availability = false }: { title: string; groups: { title: string; rows: (Assignment | { person: Person | null; detailMr?: string | null } | { textMr: string })[] }[]; onSelect?: (a: Assignment) => void; editMode?: boolean; availability?: boolean }) { return <div className="register"><SectionTitle text={title} />{groups.slice(0, 16).map((group) => <div className="register-group" key={group.title}><b>{group.title}</b>{group.rows.map((row, index) => "assignmentId" in row ? <Slot key={row.assignmentId} a={row} onSelect={onSelect!} editMode={editMode ?? false} /> : "textMr" in row ? <p key={index}>{row.textMr}</p> : <p key={index}>{personLabel(row.person)} {availability ? row.detailMr : ""}</p>)}</div>)}</div>; }
+function Slot({ a, onSelect, editMode }: { a: Assignment; onSelect: (a: Assignment) => void; editMode: boolean }) { return <button className={`slot-line ${a.isBima ? "is-bima" : ""} ${editMode ? "editable" : ""}`} onClick={() => editMode && onSelect(a)}>{personLabel(a.person)}{timeLabel(a) && <small>{timeLabel(a)}</small>}{a.notesMr && <small>{a.notesMr}</small>}{a.isBima && <i>बिमा</i>}</button>; }
+function SectionTitle({ text }: { text: string }) { return <h2 className="section-title">{text}</h2>; }
+function SimpleRows({ rows }: { rows: string[][] }) { return <div className="simple-rows">{rows.map((row, index) => <div key={index}><span>{row[0]}</span><span>{row[1]}</span></div>)}</div>; }
+function SimpleMatrix({ chart }: { chart: Chart }) { const rows = unique(chart.manpower.map((m) => m.rowKey)); const columns = unique(chart.manpower.map((m) => m.columnKey)); return <div className="matrix"><div className="matrix-row header"><span>वर्ग</span>{columns.map((column) => <span key={column}>{column}</span>)}</div>{rows.map((row) => <div className="matrix-row" key={row}><span>{row}</span>{columns.map((column) => <span key={column}>{chart.manpower.find((m) => m.rowKey === row && m.columnKey === column)?.valueText ?? ""}</span>)}</div>)}</div>; }
+
+function AssignmentEditor({ date, assignment, onClose, onSaved }: { date: string; assignment: Assignment; onClose: () => void; onSaved: () => void }) {
+    const [staff, setStaff] = useState<Staff[]>([]); const [query, setQuery] = useState(""); const [busy, setBusy] = useState(false); const [creating, setCreating] = useState(false); const [name, setName] = useState("");
+    useEffect(() => { fetch("/api/masters").then((r) => r.json()).then((data) => setStaff(data.staff ?? [])); }, []);
+    useEffect(() => { const close = (event: KeyboardEvent) => event.key === "Escape" && onClose(); document.addEventListener("keydown", close); return () => document.removeEventListener("keydown", close); }, [onClose]);
+    const results = useMemo(() => staff.filter((person) => `${person.nameMr} ${person.nameEn ?? ""} ${person.buckleNo ?? ""} ${person.rankCode ?? ""}`.toLowerCase().includes(query.toLowerCase())).slice(0, 24), [staff, query]);
+    const save = (staffId: number | null, isBima = assignment.isBima) => { setBusy(true); fetch(`/api/charts/${date}/assignments/${assignment.assignmentId}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ staffId, isBima }) }).then((r) => { if (!r.ok) throw new Error("save failed"); onSaved(); }).catch(() => setBusy(false)); };
+    const create = () => { if (!name.trim()) return; setBusy(true); fetch("/api/masters/staff", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ name_mr: name, rank_code: "PC" }) }).then((r) => r.json()).then((created) => save(Number(created.staff_id))).catch(() => setBusy(false)); };
+    return <div className="modal-backdrop" onMouseDown={(event) => event.target === event.currentTarget && onClose()}><section className="assignment-modal" role="dialog" aria-modal="true"><header><div><small>कर्मचारी नेमणूक</small><h2>{assignment.dutyTitleMr ?? assignment.roleMr ?? "कर्तव्य"}</h2></div><button onClick={onClose} aria-label="बंद करा">×</button></header><div className="modal-body"><section className="current-assignment"><small>सध्याचा कर्मचारी</small><strong>{personLabel(assignment.person)}</strong><div className="modal-actions"><button disabled={busy || !assignment.person} onClick={() => setCreating(true)}>कर्मचारी माहिती बदला</button><button className="danger" disabled={busy} onClick={() => save(null, false)}>रिक्त करा</button></div><label><input type="checkbox" checked={assignment.isBima} disabled={busy || !assignment.person} onChange={(event) => save(assignment.person?.staffId ?? null, event.target.checked)} /> या नेमणुकीसाठी बिमा</label></section><section><h3>हजर कर्मचारी निवडा</h3><input className="search-input" placeholder="नाव, बकल नंबर किंवा हुद्दा शोधा" value={query} onChange={(event) => setQuery(event.target.value)} />{results.map((person) => <button className="staff-result" key={person.staffId} onClick={() => save(person.staffId)}>{personLabel(person)}</button>)}</section><section><h3>नवीन कर्मचारी जोडा</h3>{creating ? <><input className="form-input" placeholder="नाव मराठीत" value={name} onChange={(event) => setName(event.target.value)} /><button className="primary" onClick={create} disabled={busy}>जतन करून येथे नेमा</button></> : <button onClick={() => setCreating(true)}>नवीन कर्मचारी जोडा</button>}</section></div></section></div>;
+}
+
+createRoot(document.getElementById("root")!).render(<StrictMode><App /></StrictMode>);

:root {
    font-family: "Noto Sans Devanagari", "Nirmala UI", sans-serif;
    color: #172235;
    background: #eef2f6;
    font-synthesis: none;
}

* {
    box-sizing: border-box;
}

body {
    margin: 0;
    min-width: 320px;
}

button,
a {
    font: inherit;
}

button {
    cursor: pointer;
}

.app-shell {
    min-height: 100vh;
}

.app-nav {
    min-height: 68px;
    padding: 10px 24px;
    display: flex;
    align-items: center;
    gap: 28px;
    color: #edf4ff;
    background: #0e1e38;
    border-bottom: 1px solid #2c466b;
}

.identity {
    display: flex;
    align-items: center;
    gap: 11px;
    min-width: 260px;
}

.identity img {
    width: 38px;
    height: 38px;
    object-fit: contain;
    padding: 2px;
    border-radius: 4px;
    background: white;
}

.identity div {
    display: grid;
    gap: 2px;
}

.identity strong {
    font-size: 14px;
    white-space: nowrap;
}

.identity span {
    color: #a9bad2;
    font-size: 10px;
    white-space: nowrap;
}

nav {
    display: flex;
    gap: 4px;
    align-self: stretch;
    align-items: center;
}

nav button,
.language {
    color: #b9c8dd;
    background: transparent;
    border: 0;
    padding: 8px 10px;
    font-size: 12px;
    white-space: nowrap;
    border-bottom: 2px solid transparent;
}

nav button:hover:not(:disabled),
nav .nav-active {
    color: white;
    border-bottom-color: #d2a85b;
}

nav button:disabled {
    cursor: not-allowed;
    opacity: .48;
}

.nav-actions {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-left: auto;
}

.language {
    border: 1px solid #456183;
    border-radius: 4px;
}

.date-control {
    position: relative;
}

.date-control>button {
    display: flex;
    gap: 9px;
    align-items: center;
    color: #fff;
    background: #162c4d;
    border: 1px solid #456183;
    border-radius: 4px;
    padding: 8px 10px;
    font-size: 12px;
}

.date-control>button span {
    color: #a9bad2;
    font-size: 10px;
}

.date-menu {
    position: absolute;
    z-index: 10;
    right: 0;
    top: calc(100% + 6px);
    width: 250px;
    padding: 7px;
    background: white;
    border: 1px solid #c4cfdd;
    border-radius: 5px;
    box-shadow: 0 12px 28px rgb(15 35 60 / 20%);
    color: #172235;
}

.date-menu strong {
    display: block;
    padding: 5px 7px 7px;
    color: #65758b;
    font-size: 11px;
}

.date-menu button {
    display: flex;
    width: 100%;
    justify-content: space-between;
    border: 0;
    border-radius: 3px;
    padding: 8px 7px;
    text-align: left;
    background: transparent;
    font-size: 11px;
}

.date-menu button:hover,
.date-menu .selected {
    background: #edf3fa;
}

.date-menu small {
    color: #718096;
    font-size: 9px;
    font-weight: bold;
}

.status {
    padding: 5px 7px;
    border: 1px solid #d2a85b;
    color: #f4d89b;
    border-radius: 3px;
    font-size: 10px;
    letter-spacing: .04em;
}

.print-link {
    color: #fff;
    text-decoration: none;
    border: 1px solid #456183;
    border-radius: 4px;
    padding: 7px 10px;
    font-size: 11px;
}

.workspace {
    max-width: 1540px;
    margin: 0 auto;
    padding: 24px 28px 40px;
}

.workspace-heading {
    display: flex;
    align-items: end;
    justify-content: space-between;
    gap: 20px;
    margin-bottom: 16px;
}

.eyebrow {
    margin: 0 0 3px;
    color: #65758b;
    font-size: 11px;
}

h1 {
    margin: 0;
    color: #14243c;
    font-size: 22px;
    font-weight: 700;
}

.heading-meta {
    display: flex;
    align-items: center;
    gap: 12px;
    color: #65758b;
    font-size: 12px;
}

.heading-meta a {
    color: #1f4f83;
    text-decoration: none;
}

.document-frame {
    overflow: hidden;
    background: #cbd5e1;
    border: 1px solid #b6c4d4;
    border-radius: 3px;
    box-shadow: 0 8px 24px rgb(15 35 60 / 10%);
}

.document-frame iframe {
    display: block;
    width: 100%;
    height: min(80vh, 920px);
    min-height: 640px;
    border: 0;
    background: white;
}

@media (max-width: 1100px) {
    .app-nav {
        flex-wrap: wrap;
        gap: 10px 18px;
    }

    .nav-actions {
        margin-left: 0;
        width: 100%;
    }

    nav {
        order: 3;
    }
}

@media (max-width: 650px) {
    .app-nav {
        padding: 10px 14px;
    }

    .identity {
        min-width: 0;
    }

    nav {
        width: 100%;
        overflow-x: auto;
    }

    .workspace {
        padding: 16px 10px 24px;
    }

    .workspace-heading {
        align-items: start;
        flex-direction: column;
    }

    .heading-meta {
        flex-wrap: wrap;
    }

    .document-frame {
        border-left: 0;
        border-right: 0;
        border-radius: 0;
        margin-inline: -10px;
    }

     .document-frame iframe {
        min-height: 620px;
        }
