import { StrictMode, useEffect, useMemo, useState } from "react";
import { createRoot } from "react-dom/client";
import "./styles.css";

type Person = { staffId: number; nameMr: string; rankShortFormMr?: string | null; buckleNo?: string | null; rankCode?: string };
type Assignment = { assignmentId: number; shift: "DAY" | "NIGHT"; columnNo: number; sortOrder: number; dutyCode: string | null; dutyTitleMr: string | null; location: { nameMr: string; kind: string } | null; person: Person | null; allocationState: string; isBima: boolean; startTime: string | null; endTime: string | null; notesMr: string | null; roleMr?: string | null };
type Chart = { chartDate: string; weekdayMr: string; lifecycle: string; assignments: Assignment[]; availability: { groupKey: string | null; category: string; person: Person | null; detailMr: string | null }[]; notices: { groupKey: string | null; textMr: string }[]; manpower: { rowKey: string; columnKey: string; valueText: string }[]; officerSummary: { rowNo: number; officerText: string; dutyText: string }[]; scanSchedule: { sequence: number; startTime: string | null; endTime: string | null; location: { nameMr: string } | null; person: Person | null }[] };
type ChartRef = { date: string; lifecycle: string };
type Staff = Person & { nameMr: string; nameEn?: string; phone?: string | null; active?: boolean };

const mrWeekday: Record<string, string> = { Monday: "सोमवार", Tuesday: "मंगळवार", Wednesday: "बुधवार", Thursday: "गुरुवार", Friday: "शुक्रवार", Saturday: "शनिवार", Sunday: "रविवार" };
const dayLabel = (date: string) => { const [year, month, day] = date.split("-"); return `${day}/${month}/${year}`; };
const personLabel = (person: Person | null) => person ? `${person.rankShortFormMr ?? person.rankCode ?? ""}${person.buckleNo ? ` ${person.buckleNo}` : ""} ${person.nameMr}`.trim() : "रिक्त";
const timeLabel = (a: Assignment) => a.startTime && a.endTime ? `${a.startTime.slice(0, 5)} ते ${a.endTime.slice(0, 5)}` : "";
const unique = <T,>(items: T[]) => [...new Set(items)];

function App() {
    const current = location.pathname.match(/(\d{4}-\d{2}-\d{2})/)?.[1] ?? "2026-09-10";
    const [date, setDate] = useState(current); const [charts, setCharts] = useState<ChartRef[]>([]); const [chart, setChart] = useState<Chart | null>(null);
    const [language, setLanguage] = useState<"mr" | "en">("mr"); const [menuOpen, setMenuOpen] = useState(false); const [editMode, setEditMode] = useState(false); const [selected, setSelected] = useState<Assignment | null>(null);
    const load = (next = date) => fetch(`/api/charts/${next}`).then((response) => response.json()).then(setChart);
    useEffect(() => { fetch("/api/charts").then((response) => response.json()).then(setCharts); load(); }, []);
    const jump = (next: string) => { setDate(next); setMenuOpen(false); history.pushState({}, "", `/app/charts/${next}`); load(next); window.scrollTo(0, 0); };
    return <div className="app-shell"><AppNav language={language} setLanguage={setLanguage} date={date} charts={charts} menuOpen={menuOpen} setMenuOpen={setMenuOpen} jump={jump} lifecycle={chart?.lifecycle ?? "DRAFT"} /><main className="workspace"><div className="chart-toolbar"><div><span className="eyebrow">पंचवटी तक्ता</span><h1>{language === "mr" ? "दैनिक कर्तव्य वाटप" : "Daily Duty Allocation"}</h1></div><div className="toolbar-actions"><span>{dayLabel(date)} · {chart?.weekdayMr ?? ""}</span>{chart?.lifecycle !== "FINALIZED" && <button onClick={() => setEditMode(!editMode)}>{editMode ? "पूर्वावलोकन" : "संपादन"}</button>}<a href={`/charts/${date}`} target="_blank" rel="noreferrer">प्रिंट</a></div></div>{chart ? <ChartView chart={chart} editMode={editMode} onSelect={setSelected} /> : <div className="loading">तक्ता लोड होत आहे…</div>}</main>{selected && <AssignmentEditor date={date} assignment={selected} onClose={() => setSelected(null)} onSaved={() => { setSelected(null); load(); }} />}</div>;
}

function AppNav({ language, setLanguage, date, charts, menuOpen, setMenuOpen, jump, lifecycle }: { language: "mr" | "en"; setLanguage: (v: "mr" | "en") => void; date: string; charts: ChartRef[]; menuOpen: boolean; setMenuOpen: (v: boolean) => void; jump: (v: string) => void; lifecycle: string }) {
    const weekday = new Intl.DateTimeFormat("en-US", { weekday: "long", timeZone: "UTC" }).format(new Date(`${date}T00:00:00Z`));
    return <header className="app-nav"><div className="identity"><img src="/assets/police-logo.png" alt="महाराष्ट्र पोलीस" /><div><strong>पंचवटी पोलीस ठाणे</strong><span>नाशिक शहर | Panchavati Police Station</span></div></div><nav><button className="nav-active">{language === "mr" ? "दैनिक कर्तव्य तक्ते" : "Daily Duty Charts"}</button><button disabled>{language === "mr" ? "कार्यवाही" : "Operations"}</button><button disabled>{language === "mr" ? "मास्टर डेटा" : "Master Data"}</button><button disabled>{language === "mr" ? "ऐतिहासिक शोध" : "Historical Search"}</button></nav><div className="nav-actions"><button className="language" onClick={() => setLanguage(language === "mr" ? "en" : "mr")}>{language === "mr" ? "English" : "मराठी"}</button><div className="date-control"><button onClick={() => setMenuOpen(!menuOpen)} aria-expanded={menuOpen}>{dayLabel(date)} <span>{mrWeekday[weekday]}</span>⌄</button>{menuOpen && <div className="date-menu"><strong>उपलब्ध तक्ते</strong>{charts.map((item) => <button key={item.date} className={item.date === date ? "selected" : ""} onClick={() => jump(item.date)}><span>{dayLabel(item.date)}</span><small>{item.lifecycle}</small></button>)}</div>}</div><span className="status">{lifecycle}</span></div></header>;
}

function ChartView({ chart, editMode, onSelect }: { chart: Chart; editMode: boolean; onSelect: (a: Assignment) => void }) {
    const day = chart.assignments.filter((a) => a.shift === "DAY"); const night = chart.assignments.filter((a) => a.shift === "NIGHT");
    const locations = unique(chart.assignments.filter((a) => a.location?.kind === "CHOWKI").map((a) => a.location!.nameMr));
    const grouped = (rows: Assignment[]) => unique(rows.map((a) => a.dutyTitleMr ?? a.roleMr ?? "कर्तव्य")).map((title) => ({ title, rows: rows.filter((a) => (a.dutyTitleMr ?? a.roleMr ?? "कर्तव्य") === title) }));
    const senior = day.find((a) => a.dutyCode === "DAY_STATION_LEADERSHIP" && a.person)?.person ?? null;
    return <div className="chart-document"><section className="sheet command-sheet"><div className="print-identity"><span>नाशिक शहर पोलीस आयुक्तालय</span><span>दैनिक कर्तव्य वाटप</span><span>{chart.chartDate.split("-").reverse().join("/")} · {chart.weekdayMr}</span></div><div className="senior-line">{personLabel(senior)} <b>ठाणे प्रमुख</b></div><SupportTable rows={day.filter((a) => a.columnNo === 1 && a.dutyCode !== "DAY_STATION_LEADERSHIP")} onSelect={onSelect} editMode={editMode} /><OfficerGrid chart={chart} /><div className="paired-core"><DutyLane title="दिवसपाळी" rows={day.filter((a) => a.columnNo >= 1 && a.columnNo <= 3)} groups={grouped} onSelect={onSelect} editMode={editMode} /><DutyLane title="रात्रपाळी" rows={night.filter((a) => a.columnNo >= 1 && a.columnNo <= 3)} groups={grouped} onSelect={onSelect} editMode={editMode} /></div></section><section className="sheet two-column-sheet"><DenseRegister title="कार्यालयीन शाखा व कारकून" groups={grouped(day.filter((a) => a.columnNo === 4))} onSelect={onSelect} editMode={editMode} /><DenseRegister title="रात्रपाळी सूचना व विशेष कर्तव्य" groups={grouped(night.filter((a) => a.columnNo >= 4))} onSelect={onSelect} editMode={editMode} /></section><section className="sheet chowki-sheet"><SectionTitle text="चौकी matrix" /><div className="chowki-grid">{locations.map((name) => <div className="chowki-column" key={name}><h3>{name}</h3><div className="shift-pair"><DenseRegister title="दिवस" groups={grouped(day.filter((a) => a.location?.nameMr === name))} onSelect={onSelect} editMode={editMode} /><DenseRegister title="रात्र" groups={grouped(night.filter((a) => a.location?.nameMr === name))} onSelect={onSelect} editMode={editMode} /></div></div>)}</div></section><section className="sheet two-column-sheet"><DenseRegister title="रजा व विशेष कर्तव्य" groups={unique(chart.availability.map((a) => a.groupKey ?? a.category)).map((title) => ({ title, rows: chart.availability.filter((a) => (a.groupKey ?? a.category) === title) }))} availab