ilability.filter((a) => (a.groupKey ?? a.category) === title) }))} availability /><DenseRegister title="सूचना व निर्देश" groups={unique(chart.notices.map((a) => a.groupKey ?? "सूचना")).map((title) => ({ title, rows: chart.notices.filter((a) => (a.groupKey ?? "सूचना") === title) }))} /></section><section className="sheet table-sheet"><SectionTitle text="मनुष्यबळ स्थिती दर्शक मॅट्रिक्स" /><SimpleMatrix chart={chart} /><SectionTitle text="अधिकारी सारांश" /><SimpleRows rows={chart.officerSummary.slice(0, 5).map((r) => [r.officerText, r.dutyText])} /></section><section className="sheet table-sheet"><SectionTitle text="पोलीस अधिकारी कर्तव्य सारांश" /><SimpleRows rows={chart.officerSummary.map((r) => [`${r.rowNo}. ${r.officerText}`, r.dutyText])} /><SectionTitle text="गस्त व स्कॅनिंग वेळापत्रक" /><SimpleRows rows={chart.scanSchedule.map((r) => [`${r.startTime?.slice(0, 5) ?? ""} ते ${r.endTime?.slice(0, 5) ?? ""}`, `${r.location?.nameMr ?? ""}  ${personLabel(r.person)}`])} /></section></div>;
