+
+/* Native compact-v4 screen document. It uses bands and tables instead of a nested preview. */
+.chart-toolbar { display:flex; align-items:end; justify-content:space-between; gap:20px; padding:0 0 14px; border-bottom:1px solid #c8d2df; }
+.chart-toolbar h1 { font-size:21px; }
+.toolbar-actions { display:flex; align-items:center; gap:10px; color:#52647b; font-size:12px; }
+.toolbar-actions button, .toolbar-actions a { border:1px solid #9aabc0; background:#fff; color:#1d426d; border-radius:3px; padding:6px 10px; text-decoration:none; font-size:11px; }
+.chart-document { display:grid; gap:18px; padding-top:18px; }
+.sheet { background:#fff; border:1px solid #b8c5d4; padding:16px; min-width:0; }
+.print-identity { display:flex; justify-content:space-between; gap:18px; border-bottom:1px solid #8394a8; padding:0 4px 8px; font-size:13px; font-weight:700; text-align:center; }
+.print-identity span { flex:1; }
+.senior-line { padding:10px 4px 7px; font-size:14px; white-space:nowrap; }
+.senior-line b { margin-left:8px; font-weight:500; color:#52647b; }
+.support-table, .officer-grid, .paired-core, .two-column-sheet, .chowki-grid, .shift-pair { display:grid; gap:0; }
+.support-table { grid-template-columns:repeat(auto-fit,minmax(140px,1fr)); border:1px solid #b8c5d4; }
+.support-column { min-width:0; padding:7px 9px; border-right:1px solid #cbd5e1; }
+.support-column:last-child { border-right:0; }
+.support-column>b, .duty-group>b, .register-group>b { display:block; color:#334e6f; font-size:11px; margin-bottom:3px; }
+.officer-grid { grid-template-columns:repeat(2,minmax(0,1fr)); border-left:1px solid #b8c5d4; border-top:1px solid #b8c5d4; margin-top:14px; }
+.officer-block { min-width:0; min-height:86px; padding:8px 11px; border-right:1px solid #b8c5d4; border-bottom:1px solid #b8c5d4; }
+.officer-block strong, .officer-block>span { display:block; line-height:1.25; }
+.officer-block strong { font-size:12px; }
+.officer-block>span { color:#52647b; font-size:11px; }
+.officer-block div { display:flex; flex-wrap:wrap; gap:4px 14px; margin-top:7px; color:#52647b; font-size:10px; }
+.officer-block em { font-style:normal; color:#8a5b16; }
+.paired-core { grid-template-columns:repeat(2,minmax(0,1fr)); border:1px solid #b8c5d4; margin-top:14px; }
+.duty-lane { min-width:0; padding:9px 11px; border-right:1px solid #b8c5d4; }
+.duty-lane:last-child { border-right:0; }
+.duty-lane h2, .section-title { margin:0; padding:0 0 5px; color:#173d68; border-bottom:1px solid #95a7ba; font-size:13px; font-weight:700; }
+.duty-group, .register-group { padding:5px 0; border-bottom:1px solid #e1e7ee; }
+.slot-line { display:flex; width:100%; gap:7px; align-items:baseline; border:0; padding:2px 3px; background:transparent; color:#172235; text-align:left; font-size:11px; line-height:1.3; }
+.slot-line small { color:#67788c; font-size:9.5px; }
+.slot-line i { color:#a83a2a; font-size:9px; font-style:normal; }
+.slot-line.editable { cursor:pointer; border-bottom:1px dotted #93a6bd; }
+.slot-line.editable:hover { background:#edf4fb; outline:1px solid #8aa6c3; }
+.two-column-sheet { grid-template-columns:repeat(2,minmax(0,1fr)); }
+.register { min-width:0; padding:0 11px; border-right:1px solid #b8c5d4; }
+.register:last-child { border-right:0; }
+.register p { margin:3px 0; font-size:11px; line-height:1.3; }
+.chowki-grid { grid-template-columns:repeat(3,minmax(0,1fr)); border-left:1px solid #b8c5d4; border-top:1px solid #b8c5d4; margin-top:10px; }
+.chowki-column { min-width:0; border-right:1px solid #b8c5d4; border-bottom:1px solid #b8c5d4; }
+.chowki-column h3 { margin:0; padding:7px 8px; background:#f0f4f8; color:#173d68; font-size:12px; }
+.shift-pair { grid-template-columns:repeat(2,minmax(0,1fr)); }
+.shift-pair .register { padding:7px; border-top:1px solid #d4dde7; font-size:10px; }
+.shift-pair .section-title { font-size:10px; }
+.table-sheet { overflow:auto; }
+.matrix { display:grid; margin:10px 0 16px; min-width:620px; border-left:1px solid #c3cedb; border-top:1px solid #c3cedb; }
+.matrix-row { display:grid; grid-template-columns:150px repeat(auto-fit,minmax(70px,1fr)); }
+.matrix-row span { min-height:26px; padding:5px 6px; border-right:1px solid #c3cedb; border-bottom:1px solid #c3cedb; font-size:10px; white-space:pre-wrap; }
+.matrix-row.header span { background:#f0f4f8; color:#284b70; font-weight:700; }
+.simple-rows { display:grid; margin:9px 0 15px; border-top:1px solid #c3cedb; }
+.simple-rows div { display:grid; grid-template-columns:minmax(160px,1fr) minmax(0,2fr); border-bottom:1px solid #dce4ec; }
+.simple-rows span { padding:5px 6px; font-size:11px; }
+.simple-rows span:first-child { color:#334e6f; }
+.loading { padding:60px; text-align:center; color:#65758b; }
+.modal-backdrop { position:fixed; inset:0; z-index:20; display:flex; align-items:center; justify-content:center; padding:20px; background:rgb(13 29 51 / 48%); }
+.assignment-modal { width:min(590px,100%); max-height:86vh; overflow:auto; background:#fff; border:1px solid #afbdcc; border-radius:6px; box-shadow:0 18px 55px rgb(8 25 47 / 28%); }
+.assignment-modal>header { display:flex; justify-content:space-between; align-items:center; padding:13px 16px; background:#173b65; color:#fff; }
+.assignment-modal header h2 { margin:2px 0 0; font-size:15px; }
+.assignment-modal header small { color:#c5d4e6; font-size:10px; }
+.assignment-modal header button { border:0; background:transparent; color:#fff; font-size:22px; }
+.modal-body { display:grid; gap:14px; padding:15px; }
+.modal-body section { padding-bottom:13px; border-bottom:1px solid #dfe6ee; }
+.modal-body h3, .modal-body small { display:block; margin:0 0 7px; color:#274b71; font-size:12px; }
+.current-assignment { display:grid; gap:7px; }
+.current-assignment strong { font-size:13px; }
+.modal-actions { display:flex; gap:7px; flex-wrap:wrap; }
+.modal-body button, .search-input, .form-input { border:1px solid #bdcad8; border-radius:3px; background:#fff; color:#1e456e; padding:7px 9px; font-size:11px; }
+.modal-body button:hover { background:#eef4fa; }
+.modal-body button:disabled { opacity:.5; cursor:not-allowed; }
+.modal-body .danger { color:#a13c32; border-color:#e4b4ae; }
+.modal-body label { color:#52647b; font-size:11px; }
+.search-input, .form-input { width:100%; margin-bottom:7px; color:#172235; }
+.staff-result { display:block; width:100%; margin:3px 0; text-align:left; }
+.primary { background:#173b65 !important; color:#fff !important; border-color:#173b65 !important; }
+@media (max-width:800px) { .app-nav { gap:10px 18px; } .chart-toolbar, .print-identity { align-items:flex-start; flex-direction:column; } .toolbar-actions { flex-wrap:wrap; } .two-column-sheet, .paired-core { grid-template-columns:1fr; } .register { border-right:0; border-bottom:1px solid #b8c5d4; padding:10px 0; } .chowki-grid { grid-template-columns:repeat(2,minmax(0,1fr)); } .print-identity { gap:3px; } .print-identity span { flex:auto; } }
+@media (max-width:540px) { .workspace { padding-inline:10px; } .sheet { padding:10px; } .chowki-grid, .officer-grid { grid-template-columns:1fr; } .support-table { grid-template-columns:repeat(2,minmax(0,1fr)); } .support-column { border-bottom:1px solid #cbd5e1; } .identity span { display:none; } }
*** End Patch","explanation":"Replace the nested-preview styling with compact document bands, paired columns, chowki matrix, dense registers, and a centered viewport-safe assignment editor."}

