.flyer-body{padding:14px 16px; overflow-y:auto; display:flex; flex-direction:column; gap:12px;}
.flyer-opt{
  border:1px solid #e2e8f0; border-radius:6px; padding:9px 11px; cursor:pointer; background:#fff;
}
.flyer-opt:hover{border-color:#2c5282; background:#f0f7ff;}
.flyer-opt.disabled{opacity:.5; cursor:not-allowed; border-color:#e2e8f0; background:#f8fafc;}
.flyer-opt h4{font-size:12px; font-weight:700; color:#0b3568; margin-bottom:2px;}
.flyer-opt p{font-size:11px; color:#64748b;}
.flyer-search{width:100%; padding:6px 10px; border:1px solid #cbd5e1; border-radius:4px; font-size:12px; margin-top:8px;}
.flyer-list{max-height:160px; overflow-y:auto; border:1px solid #e2e8f0; border-radius:4px; margin-top:6px; background:#fff;}
.flyer-item{padding:5px 8px; font-size:11.5px; border-bottom:1px solid #f1f5f9; cursor:pointer;}
.flyer-item:hover{background:#e0ecf8; color:#0b3568; font-weight:600;}
.flyer-item .sg{
  display:inline-block; margin-left:6px; font-size:9.5px; font-weight:700;
  color:#15803d; background:#ecfdf3; border:1px solid #bbf7d0; border-radius:8px; padding:0 5px;
  vertical-align:1px;
}
.flyer-item.sg-top{background:#f0fdf4;}
.flyer-mini-form{display:flex; flex-direction:column; gap:6px; margin-top:8px;}
.flyer-mini-form input, .flyer-mini-form select{padding:5px 8px; font-size:11.5px; border:1px solid #cbd5e1; border-radius:4px;}
.flyer-btn-submit{background:#0b3568; color:#fff; border:none; padding:6px 12px; border-radius:4px; font-size:11.5px; font-weight:700; cursor:pointer; align-self:flex-start; margin-top:4px;}
.flyer-btn-submit:hover{background:#1e3a5f;}
.flyer-btn-ghost{
  background:#fff; color:#0b3568; border:1px solid #cbd5e1; padding:5px 10px;
  border-radius:4px; font-size:11.5px; font-weight:600; cursor:pointer;
}
.flyer-btn-ghost:hover{background:#f0f7ff; border-color:#2c5282;}
.flyer-btn-danger{background:#fff; color:#b42318; border:1px solid #fecdd3; padding:5px 10px; border-radius:4px; font-size:11.5px; font-weight:600; cursor:pointer;}
.flyer-btn-danger:hover{background:#fff1f2;}
.flyer-actions{display:flex; gap:8px; flex-wrap:wrap; margin-top:4px;}
.flyer-slot-info{font-size:12px; font-weight:700; color:#1e293b; padding-bottom:6px; border-bottom:1px solid #e2e8f0;}
/* rename flyer: scope choice (this element only / everywhere with this default name) */
.rn-scope{ font-size:11.5px; display:flex; gap:6px; align-items:center; color:#334155; margin:3px 0; cursor:pointer; }
.rn-scope input{ margin:0; }

/* ---- toast (success/error feedback, no-print) ------------------------------ */
.toast{
  position:fixed; bottom:18px; left:50%; transform:translateX(-50%); z-index:200;
  background:#0f172a; color:#fff; padding:9px 16px; border-radius:6px;
  font-size:12.5px; font-weight:600; box-shadow:0 8px 24px rgba(0,0,0,.3);
  max-width:90vw;
}
.toast.ok{background:#14532d;}
.toast.err{background:#7f1d1d;}

/* ---- print density: composite sheets whose real content exceeds one A4 -----
   The mock's type scale fits a page when its sample data is small; the 10/09 source
   carries ~2× that volume on the command band (page 1) and the leave/court page. Those
   two sheets get `.page.dense` from the renderer, which tightens row padding and type
   in PRINT only (screen keeps the mock's generous scale). Values are never dropped,
   truncated or reordered — only row metrics change, and no size goes below 9.5px. */
@media print{
  .page.dense .head{padding:0 0 2px; margin-bottom:3px;}
  .page.dense .head .hc .h1{font-size:13px; line-height:1.2;} .page.dense .head .hc .h2{font-size:11px; line-height:1.2;}
  .page.dense .head .hc .h3{font-size:10px;}
  .page.dense .sec{margin:5px 0 2px;} .page.dense .sec h2{font-size:11px;}
  .page.dense .grid{gap:4px;} .page.dense .p1-lower{gap:5px; margin-top:5px;}
  .page.dense .sr-pi-card{margin:0 auto 4px;} .page.dense .sr-pi-body{padding:3px 10px; font-size:11px; line-height:1.2;}
  .page.dense .blk > .bh{padding:2px 6px;} .page.dense .blk .bh .nm{font-size:11px;}
  .page.dense .blk .body{padding:3px 6px; gap:1.5px;}
  .page.dense .dt{font-size:9.5px;} .page.dense .dt th{font-size:9.5px; padding:1px 5px 1px 0;}
  .page.dense .dt td{padding:1px 0;} .page.dense .core .dt th{padding-right:10px;}
  .page.dense .p{font-size:10px; padding:1px 0;} .page.dense .p .r{font-size:9.5px;}
  .page.dense .g-off .blk .body .dt{font-size:9.5px;}
  /* row metrics: 20–36 source rows per block only fit a sheet when a row is ~15px.
     Values wrap, they are never truncated. */
  .page.dense .dt td, .page.dense .p, .page.dense .dt th{line-height:1.15;}
  /* leave/court lists: the mock's 4 columns leave whole grid rows half empty when one
     list (साप्ताहिक सुट्टी, 20 people) is far longer than its neighbours — six columns
     let the long lists share the sheet instead of forcing a second one. */
  .page.dense .grid.g4{grid-template-columns:repeat(6,1fr);}
}

/* ---- print: authoring chrome NEVER prints --------------------------------- */
@media print{
  .add-box, .toast, .flyer-overlay, .flyer-card{ display:none !important; }
  abbr.abbr{ border-bottom:0 !important; }
  abbr.abbr::after{ display:none !important; }
  body.mode-edit .dt td.slot{ outline:none !important; background:transparent !important; cursor:auto; }
  body.mode-edit .dt td.slot:hover::after{ content:none !important; }
  body.mode-edit [data-label]{ cursor:auto !important; }
  body.mode-edit [data-label]:hover, body.mode-edit [data-label]:focus{
    outline:none !important; background:transparent !important;
  }
}

