/* ============================================================================
   Panchavati Daily Duty Chart — authoring UI stylesheet (production)
   Purpose: edit-mode affordances, staff picker flyer, abbreviation tooltips,
     add-box controls, toasts — everything that is NOT the frozen visual baseline.
   Current role: served by the Fastify app (GET /authoring.css) and linked by the
     server-rendered chart page; design/compv3.css remains the approved reference.
   Last meaningful change: 2026-10-09 — created by MOVING the mode-edit/flyer
     styles out of compv3.css (whose header always claimed they were removed),
     scoping them to real slots, and adding add-box/abbr/toast styles.
   Constraint/dependency: every rule here is killed under @media print; baseline
     compv3.css is human-owned — authoring styles change HERE, never there.
   ============================================================================ */

/* ---- app header (Arjish AppNav grammar ported to server-rendered HTML) -------
   Screen-only chrome: the whole bar is `.no-print`, so the printed sheets keep their own
   head. Structure = emblem + station + product title on the left, date control + status +
   actions + signed-in clerk on the right. */
.toolbar#appbar{
  background:#0e1e38; border-bottom:1px solid #1b2e4f; padding:0 16px;
  min-height:56px; gap:10px; flex-wrap:nowrap; align-items:center;
}
#appbar .ab-l{display:flex; align-items:center; gap:12px; min-width:0;}
#appbar .ab-logo{height:34px; width:auto; border-radius:4px; background:#fff; padding:2px; flex:none;}
#appbar .ab-st{display:flex; flex-direction:column; line-height:1.25; min-width:0;}
#appbar .ab-st b{font-size:14px; font-weight:700; color:#fff; white-space:nowrap;}
#appbar .ab-st span{font-size:10.5px; color:#94a3b8; white-space:nowrap;}
#appbar .ab-sep{width:1px; height:26px; background:rgba(255,255,255,.2);}
#appbar .ab-nav{display:flex; align-items:center; gap:4px; min-width:0; margin-left:14px;}
#appbar .ab-nav a, #appbar .ab-nav .planned{display:inline-flex; align-items:center; gap:5px; padding:7px 8px; color:#b9c8dd; border-bottom:2px solid transparent; font-size:11px; text-decoration:none; white-space:nowrap;}
#appbar .ab-nav a.active{color:#fff; border-bottom-color:#d2a85b;}
#appbar .ab-nav .planned{cursor:not-allowed; opacity:.55;}
#appbar .ab-nav small{font-size:8px; color:#d2a85b; text-transform:uppercase; letter-spacing:.03em;}
#appbar .ab-r{display:flex; align-items:center; gap:8px; margin-left:auto; flex-wrap:nowrap;}
#appbar .ab-datewrap{position:relative;}
#appbar .ab-datebtn{
  display:inline-flex; align-items:center; gap:8px; background:rgba(255,255,255,.06);
  border:1px solid #33456b; color:#fff; padding:6px 10px; border-radius:6px; min-height:34px;
}
#appbar .ab-datebtn::before{content:"🗓"; font-size:13px;}
#appbar .ab-datebtn .d{font-weight:700; font-size:13px; white-space:nowrap;}
#appbar .ab-datebtn .w{color:#93a8c8; font-size:11.5px; white-space:nowrap;}
#appbar .ab-datebtn .cv{color:#93a8c8; font-size:10px;}
#appbar .ab-datebtn:hover{background:rgba(255,255,255,.12);}
#appbar .ab-datemenu{
  position:absolute; top:calc(100% + 6px); right:0; z-index:70; min-width:230px;
  max-height:320px; overflow-y:auto; background:#fff; color:#0f172a;
  border:1px solid #cbd5e1; border-radius:8px; box-shadow:0 12px 28px rgba(2,8,23,.35); padding:6px;
}
#appbar .ab-datemenu .dm-head{font-size:10.5px; font-weight:700; color:#64748b; padding:4px 8px 6px;}
#appbar .ab-datemenu .dm-item{
  display:flex; justify-content:space-between; align-items:center; gap:10px;
  padding:7px 8px; border-radius:5px; cursor:pointer; font-size:12px; font-weight:600;
}
#appbar .ab-datemenu .dm-item:hover, #appbar .ab-datemenu .dm-item:focus{background:#eef4fb; outline:none;}
#appbar .ab-datemenu .dm-item.cur{background:#0e1e38; color:#fff;}
#appbar .ab-datemenu .dm-item .st{font-size:9.5px; font-weight:700; letter-spacing:.3px; color:#64748b;}
#appbar .ab-datemenu .dm-item.cur .st{color:#cbd5e1;}
#appbar .ab-user{
  background:rgba(255,255,255,.06); border:1px solid #33456b; color:#e2e8f0;
  padding:6px 10px; border-radius:6px; font-size:11.5px; font-weight:600; max-width:38ch;
  overflow:hidden; text-overflow:ellipsis; white-space:nowrap;
}
#appbar .ab-user:hover{background:rgba(255,255,255,.12);}
#appbar .ab-user.on{background:#14532d; border-color:#166534; color:#dcfce7;}
.chart-toolbar{display:flex; align-items:center; justify-content:space-between; gap:14px; min-height:45px; padding:7px 16px; background:#f7f9fc; border-bottom:1px solid #cbd5e1; color:#173b65;}
.chart-toolbar .ct-title{display:flex; align-items:baseline; gap:12px; min-width:0; font-size:13px; font-weight:700;}
.chart-toolbar .ct-title strong{color:#64748b; font-size:11px; font-weight:500; white-space:nowrap;}
.chart-toolbar .ct-actions{display:flex; align-items:center; gap:7px; flex:none;}
.chart-toolbar button{padding:5px 9px; border:1px solid #b6c4d4; border-radius:4px; background:#fff; color:#173b65; font:inherit; font-size:11px;}
.chart-toolbar button:hover{background:#edf3fa;}
.chart-toolbar button.finalize{background:#176b43; border-color:#176b43; color:#fff;}
.chart-toolbar .lc{padding:4px 7px;}
/* Compact-v4 printed identity: four information groups share one horizontal line. */
.page .head{display:flex; align-items:center; justify-content:space-between; gap:12px; min-height:31px; padding:4px 8px;}
.page .head .hc{display:flex; align-items:baseline; justify-content:center; gap:18px; min-width:0; flex:1; text-align:center;}
.page .head .h1, .page .head .h2, .page .head .h3{display:inline; margin:0; white-space:nowrap;}
.page .head .h1{font-size:13px; font-weight:700;}
.page .head .h2{font-size:12px; font-weight:600;}
.page .head .h3{font-size:11px; color:var(--ink-soft);}
.page .head .hr{flex:none;}
@media screen and (max-width:1025px){
  #appbar{flex-wrap:wrap; padding:6px 12px;}
  #appbar .ab-nav{margin-left:0; width:100%; overflow-x:auto; order:3;}
  #appbar .ab-st-2, #appbar .ab-sep{display:none;}
  .chart-toolbar{align-items:flex-start; flex-wrap:wrap;}
  .page .head .hc{gap:10px; flex-wrap:wrap;}
}

/* ---- edit-mode slot affordances (hover/focus outline + pencil, real slots) --- */
body.mode-edit .dt td.slot{
  cursor:pointer; transition:background .15s ease, outline .15s ease;
}
body.mode-edit .dt td.slot:hover{
  outline:1px dashed var(--navy-3); background:#f0f7ff; border-radius:2px;
}
body.mode-edit .dt td.slot:focus{
  outline:2px solid #2563eb; background:#eff6ff;
}
/* Hover must not change the geometry: injecting the ✎ glyph re-flowed the cell text and made
   the whole row jump/flicker on every hover. The affordance is now pure outline + tint. */
body.mode-edit .dt td.slot:hover{ background-image:none; }
body.mode-edit .dt td.slot{ outline-offset:-1px; }

/* ---- editable display names (section / table / column / left-row titles) ------
   Every rename-able name carries data-label + data-default from the renderer. Edit mode
   shows the SAME effect as slots: dashed outline + tint, geometry identical hovered or
   not — no content injection on hover (that is what made cells flicker/reflow before). */
body.mode-edit [data-label]{ cursor:text; border-radius:2px; }
body.mode-edit [data-label]:hover{
  outline:1px dashed var(--navy-3); outline-offset:1px; background:#f0f7ff;
}
body.mode-edit [data-label]:focus{
  outline:2px solid #2563eb; outline-offset:1px; background:#eff6ff;
}

/* ---- chowki band: keep state lines whole (chart layout correction) ----------
   These apply on screen AND in print (unlike the edit chrome above/below). The baseline
   wraps `.fx` mid-phrase ("चार्ज →" then an orphan word on the next line); the state words
   stay together here and only the destination phrase wraps, so nothing looks broken and
   nothing spills out of its column. */
.fx{ text-wrap:pretty; }
.fx .lb, .fx .st{ white-space:nowrap; }
.fx .dst{ overflow-wrap:break-word; }
.sub-col-title span{ text-wrap:pretty; }
.ch-head .of{ text-wrap:pretty; }
