  background:#fff; border-radius:8px; box-shadow:0 10px 25px -5px rgba(0,0,0,.25);
  width:min(440px, 94vw); max-height:85vh; display:flex; flex-direction:column; overflow:hidden;
  border:1px solid #cbd5e1;
}
.flyer-header{
  padding:12px 16px; background:#0b3568; color:#fff;
  display:flex; align-items:center; justify-content:space-between;
}
.flyer-header h3{font-size:14px; font-weight:700;}
.flyer-close{background:none; border:none; color:#cbd5e1; font-size:18px; cursor:pointer;}
.flyer-close:hover{color:#fff;}
.flyer-body{padding:14px 16px; overflow-y:auto; display:flex; flex-direction:column; gap:12px;}
.flyer-opt{
  border:1px solid #e2e8f0; border-radius:6px; padding:9px 11px; cursor:pointer; background:#fff;
}
.flyer-opt:hover{border-color:#2c5282; background:#f0f7ff;}
.flyer-opt.disabled{opacity:.5; cursor:not-allowed; border-color:#e2e8f0; background:#f8fafc;}
.flyer-opt h4{font-size:12px; font-weight:700; color:#0b3568; margin-bottom:2px;}
.flyer-opt p{font-size:11px; color:#64748b;}
.flyer-search{width:100%; padding:6px 10px; border:1px solid #cbd5e1; border-radius:4px; font-size:12px; margin-top:8px;}
.flyer-list{max-height:160px; overflow-y:auto; border:1px solid #e2e8f0; border-radius:4px; margin-top:6px; background:#fff;}
.flyer-item{padding:5px 8px; font-size:11.5px; border-bottom:1px solid #f1f5f9; cursor:pointer;}
