  text-align: center;
}

.page .head .h1,
.page .head .h2,
.page .head .h3 {
  display: inline;
  margin: 0;
  white-space: nowrap;
}

.page .head .h1 {
  font-size: 13px;
  font-weight: 700;
}

.page .head .h2 {
  font-size: 12px;
  font-weight: 600;
}

.page .head .h3 {
  font-size: 11px;
  color: var(--ink-soft);
}

.page .head .hr {
  flex: none;
}

@media screen and (max-width:1025px) {
  #appbar {
    flex-wrap: wrap;
    padding: 6px 12px;
  }

  #appbar .ab-nav {
    margin-left: 0;
    width: 100%;
    overflow-x: auto;
    order: 3;
  }

  #appbar .ab-st-2,
  #appbar .ab-sep {
    display: none;
  }

  .chart-toolbar {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .page .head .hc {
    gap: 10px;
    flex-wrap: wrap;
  }
}

/* ---- edit-mode slot affordances (hover/focus outline + pencil, real slots) --- */
body.mode-edit .dt td.slot {
  cursor: pointer;
  transition: background .15s ease, outline .15s ease;
}

body.mode-edit .dt td.slot:hover {
  outline: 1px dashed var(--navy-3);
  background: #f0f7ff;
  border-radius: 2px;
}

body.mode-edit .dt td.slot:focus {
  outline: 2px solid #2563eb;
  background: #eff6ff;
}

/* Hover must not change the geometry: injecting the ✎ glyph re-flowed the cell text and made
   the whole row jump/flicker on every hover. The affordance is now pure outline + tint. */
body.mode-edit .dt td.slot:hover {
  background-image: none;
}

body.mode-edit .dt td.slot {
  outline-offset: -1px;
}

/* ---- editable display names (section / table / column / left-row titles) ------
   Every rename-able name carries data-label + data-default from the renderer. Edit mode
   shows the SAME effect as slots: dashed outline + tint, geometry identical hovered or
   not — no content injection on hover (that is what made cells flicker/reflow before). */
body.mode-edit [data-label] {
  cursor: text;
  border-radius: 2px;
}

body.mode-edit [data-label]:hover {
  outline: 1px dashed var(--navy-3);
  outline-offset: 1px;
  background: #f0f7ff;
}

body.mode-edit [data-label]:focus {
  outline: 2px solid #2563eb;
  outline-offset: 1px;
  background: #eff6ff;
}

/* ---- chowki band: keep state lines whole (chart layout correction) ----------
   These apply on screen AND in print (unlike the edit chrome above/below). The baseline
   wraps `.fx` mid-phrase ("चार्ज →" then an orphan word on the next line); the state words
   stay together here and only the destination phrase wraps, so nothing looks broken and
   nothing spills out of its column. */
.fx {
  text-wrap: pretty;
}

.fx .lb,
.fx .st {
  white-space: nowrap;
}

.fx .dst {
  overflow-wrap: break-word;
}

.sub-col-title span {
  text-wrap: pretty;
}

.ch-head .of {
  text-wrap: pretty;
}

.dt td,
.dt th {
  text-wrap: pretty;
}

/* ---- contextual add-box controls (edit mode only; never printed) ------------ */
.add-box {
  display: none;
}

body.mode-edit .add-box {
  display: block;
  width: 100%;
  margin-top: 8px;
  padding: 7px 10px;
  border: 1.5px dashed var(--navy-3);
  border-radius: 4px;
  background: #f7fafd;
  color: var(--navy);
  font-size: 11.5px;
  font-weight: 700;
  font-family: inherit;
  text-align: center;
  cursor: pointer;
}

body.mode-edit .add-box:hover:not(:disabled) {
  background: #eaf0f8;
  border-color: var(--navy);
}

body.mode-edit .add-box:disabled {
  opacity: .55;
  cursor: not-allowed;
  border-color: var(--line);
  color: var(--ink-faint);
}

body.mode-edit .add-box:focus-visible {
  outline: 2px solid #2563eb;
  outline-offset: 1px;
}

/* ---- abbreviation tooltip (hover AND keyboard focus; preview only) ---------- */
abbr.abbr {
  font-style: normal;
  text-decoration: none;
  cursor: help;
  border-bottom: 1px dotted var(--ink-faint);
  position: relative;
}

abbr.abbr:hover,
abbr.abbr:focus {
  border-bottom-color: var(--navy);
  outline: none;
}

abbr.abbr:focus {
  border-bottom-style: solid;
}

abbr.abbr::after {
  content: attr(data-full);
  position: absolute;
  left: 0;
  top: 100%;
  margin-top: 3px;
  z-index: 60;
  background: var(--navy);
  color: #fff;
  font-size: 10.5px;
  font-weight: 600;
  font-style: normal;
  padding: 3px 7px;
  border-radius: 4px;
  white-space: normal;
  max-width: 220px;
  opacity: 0;
  visibility: hidden;
  transition: opacity .12s ease;
  box-shadow: 0 4px 10px rgba(0, 0, 0, .22);
  pointer-events: none;
}

abbr.abbr:hover::after,
abbr.abbr:focus::after {
  opacity: 1;
  visibility: visible;
}

/* ---- 3-option staff picker flyer (moved from compv3.css, 502-round) --------- */
.flyer-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
