/* ---- print density: composite sheets whose real content exceeds one A4 -----
   The mock's type scale fits a page when its sample data is small; the 10/09 source
   carries ~2× that volume on the command band (page 1) and the leave/court page. Those
   two sheets get `.page.dense` from the renderer, which tightens row padding and type
   in PRINT only (screen keeps the mock's generous scale). Values are never dropped,
   truncated or reordered — only row metrics change, and no size goes below 9.5px. */
@media print {
  .page.dense .head {
    padding: 0 0 2px;
    margin-bottom: 3px;
  }

  .page.dense .head .hc .h1 {
    font-size: 13px;
    line-height: 1.2;
  }

  .page.dense .head .hc .h2 {
    font-size: 11px;
    line-height: 1.2;
  }

  .page.dense .head .hc .h3 {
    font-size: 10px;
  }

  .page.dense .sec {
    margin: 5px 0 2px;
  }

  .page.dense .sec h2 {
    font-size: 11px;
  }

  .page.dense .grid {
    gap: 4px;
  }

  .page.dense .p1-lower {
    gap: 5px;
    margin-top: 5px;
  }

  .page.dense .sr-pi-card {
    margin: 0 auto 4px;
  }

  .page.dense .sr-pi-body {
    padding: 3px 10px;
    font-size: 11px;
    line-height: 1.2;
  }

  .page.dense .blk>.bh {
    padding: 2px 6px;
  }

  .page.dense .blk .bh .nm {
    font-size: 11px;
  }

  .page.dense .blk .body {
    padding: 3px 6px;
    gap: 1.5px;
  }

  .page.dense .dt {
    font-size: 9.5px;
  }

  .page.dense .dt th {
    font-size: 9.5px;
    padding: 1px 5px 1px 0;
  }

  .page.dense .dt td {
    padding: 1px 0;
  }

  .page.dense .core .dt th {
    padding-right: 10px;
  }

  .page.dense .p {
    font-size: 10px;
    padding: 1px 0;
  }

  .page.dense .p .r {
    font-size: 9.5px;
  }

  .page.dense .g-off .blk .body .dt {
    font-size: 9.5px;
  }

  /* Page 1 has the command hierarchy plus two paired core tables. Tighten only its
     internal block metrics; other dense sheets retain the normal readable density. */
  .page.command .g-off,
  .page.command .g-core {
    gap: 3px;
  }

  .page.command .g-off .blk .body,
  .page.command .g-core .blk .body {
    padding: 2px 5px;
    gap: 1px;
  }

  .page.command .g-off .dt td,
  .page.command .g-off .dt th,
  .page.command .g-core .dt td,
  .page.command .g-core .dt th {
    line-height: 1.08;
  }

  /* row metrics: 20–36 source rows per block only fit a sheet when a row is ~15px.
     Values wrap, they are never truncated. */
  .page.dense .dt td,
  .page.dense .p,
  .page.dense .dt th {
    line-height: 1.15;
  }

  /* leave/court lists: the mock's 4 columns leave whole grid rows half empty when one
     list (साप्ताहिक सुट्टी, 20 people) is far longer than its neighbours — six columns
     let the long lists share the sheet instead of forcing a second one. */
  .page.dense .grid.g4 {
    grid-template-columns: repeat(6, 1fr);
  }
}

/* ---- print: authoring chrome NEVER prints --------------------------------- */
@media print {

  .add-box,
  .toast,
  .flyer-overlay,
  .flyer-card {
    display: none !important;
  }

  abbr.abbr {
    border-bottom: 0 !important;
  }

  abbr.abbr::after {
    display: none !important;
  }

  body.mode-edit .dt td.slot {
    outline: none !important;
    background: transparent !important;
    cursor: auto;
  }

  body.mode-edit .dt td.slot:hover::after {
    content: none !important;
  }

  body.mode-edit [data-label] {
    cursor: auto !important;
  }

  body.mode-edit [data-label]:hover,
  body.mode-edit [data-label]:focus {
    outline: none !important;
    background: transparent !important;
  }
}

