import pg from 'pg';
const pool = new pg.Pool({ database: 'panchavati3_dev', user: 'postgres', host: '127.0.0.1' });
const run = async () => {
  const q = async (sql) => (await pool.query(sql)).rows;
  console.log('ASSIGNMENTS BY SHIFT/COLUMN');
  console.table(await q(`SELECT shift, column_no, count(*)::int AS rows, count(*) FILTER (WHERE staff_id IS NOT NULL)::int AS staffed, count(*) FILTER (WHERE staff_id IS NULL)::int AS vacant FROM daily_assignments a JOIN daily_charts c USING(chart_id) WHERE c.chart_date='2026-09-10' GROUP BY shift,column_no ORDER BY shift,column_no`));
  console.log('ASSIGNMENTS BY SHIFT/COLUMN/LOCATION');
  console.table(await q(`SELECT shift, column_no, coalesce(l.name_mr,'(location-less)') AS location, count(*)::int AS rows, count(*) FILTER (WHERE staff_id IS NOT NULL)::int AS staffed FROM daily_assignments a JOIN daily_charts c USING(chart_id) LEFT JOIN locations l USING(location_id) WHERE c.chart_date='2026-09-10' GROUP BY shift,column_no,l.name_mr ORDER BY shift,column_no,location`));
  console.log('TOP DUTY GROUPS');
  console.table(await q(`SELECT shift, column_no, coalesce(a.duty_title_mr,d.title_mr,'(untitled)') AS duty, count(*)::int AS rows, count(*) FILTER (WHERE staff_id IS NOT NULL)::int AS staffed FROM daily_assignments a JOIN daily_charts c USING(chart_id) LEFT JOIN duty_definitions d USING(duty_id) WHERE c.chart_date='2026-09-10' GROUP BY shift,column_no,duty ORDER BY shift,column_no,min(a.sort_order)`));
  console.log('LOCATION STATES');
  console.table(await q(`SELECT s.shift,l.name_mr,s.is_closed,coalesce(ch.name_mr,'') AS charge_to FROM location_operational_states s JOIN daily_charts c USING(chart_id) JOIN locations l ON l.location_id=s.location_id LEFT JOIN locations ch ON ch.location_id=s.charge_destination_location_id WHERE c.chart_date='2026-09-10' ORDER BY s.shift,l.display_order`));
  await pool.end();
}; run().catch(e=>{console.error(e);process.exit(1)});
